"""Saved latest full-corpus contraction, no numerical candidate/reference call."""
import json,math,hashlib
from pathlib import Path
P=Path(__file__).resolve().parent
bs=[json.loads((P/f'full_{i}.json').read_text()) for i in range(8)];assert all(b['complete'] for b in bs)
rows=[r for b in bs for r in b['rows']];assert len(rows)==35098 and {r['index'] for r in rows}==set(range(35098));assert sum(r['reused'] for r in rows)==266
s=dict(cases=len(rows),reused_once=266,source_error_mass=math.fsum(r['value'] for r in rows),positive_error_mass=math.fsum(r['reference'] for r in rows),signed_error=math.fsum(r['difference'] for r in rows),L1_error=math.fsum(abs(r['difference']) for r in rows),max_abs_error=max(abs(r['difference']) for r in rows),max_relative_error=max(abs(r['difference'])/r['reference'] for r in rows if r['reference']>0),reference_bound_sum=math.fsum(r['reference_bound'] for r in rows),reference_only_bound_exceedances=sum(abs(r['difference'])>r['reference_bound'] for r in rows),gate_exceedances=sum(abs(r['difference'])>1e-10+r['reference_bound'] for r in rows),negative_values=sum(r['value']<0 for r in rows),parity_failures=sum(not r['parity'] for r in rows),thin=sum(r['diagnostics']['branch']=='duffy10' for r in rows),wide=sum(r['diagnostics']['branch']=='log128_atan2' for r in rows),source_cpu_once=math.fsum(r['source_cpu'] for r in rows),observer_cpu_once=math.fsum(r['diagnostic_cpu'] for r in rows),legacy_ops_once=sum(r['legacy_ops'] for r in rows),shard_cpu=math.fsum(b['cpu'] for b in bs),max_unit_diagonal_drift=max(r['diagnostics'].get('max_unit_diagonal_drift',0) for r in rows),min_observed_thin_q=min(r['diagnostics']['q_min'] for r in rows if r['diagnostics']['branch']=='duffy10'))
for k in ['raw_negative_detRt','raw_zero_detRt','angle_nonfinite','denominator_floor_hits','inverse_calls','scalar3det_calls','scalar4det_calls']:s[k]=sum(r['diagnostics'].get(k,0) for r in rows)
s['finite_gate_pass']=s['gate_exceedances']==0 and s['parity_failures']==0
s['source_accuracy']=1-s['source_error_mass'];s['positive_accuracy']=1-s['positive_error_mass'];s['accuracy_difference']=s['source_accuracy']-s['positive_accuracy']
s['worst_abs10']=[{k:r[k] for k in ['index','value','reference','difference','reference_bound','diagnostics']} for r in sorted(rows,key=lambda r:abs(r['difference']),reverse=True)[:10]]
s['worst_relative10']=[{k:r[k] for k in ['index','value','reference','difference','reference_bound']} for r in sorted(rows,key=lambda r:abs(r['difference'])/r['reference'] if r['reference']>0 else -1,reverse=True)[:10]]
s['pins']={f.name:hashlib.sha256(f.read_bytes()).hexdigest() for pat in ['full_[0-7].json','full_nodes_*.npz','panel.json','controls.json','full_protocol.json','audit.py','full.py','estT_snapshot.py'] for f in P.glob(pat)}
s['scope']='Latest139a7b9e finite actual corpus only. Generic thin stress fails remain. Ordinaryfloating, conditional reference bounds only, no complete native-cost or universal guarantee. Reused266 source/observer costs once; controls/setup/hash/storage separate review costs. Min observed q is not global radial lower bound.'
(P/'full_summary.json').write_text(json.dumps(s,indent=2,allow_nan=False)+'\n');print(json.dumps({k:v for k,v in s.items() if k not in ['pins','worst_abs10','worst_relative10']}))
